1	package main
2	
3	import (
4		"flag"
5		"fmt"
6		"io"
7		"net/netip"
8		"regexp"
9		"strings"
10		"time"
11	
12		"github.com/anthnel/devdesk/internal/nexusbench"
13	)
14	
15	// Defaults of the flags that are not a NEXUS_BENCH_* parameter.
16	const (
17		loopbackHost = "127.0.0.1"
18		maxHostLen   = 253
19	)
20	
21	var (
22		// hostName is a DNS name: letters, digits, '.' and '-', no port, no path,
23		// no credentials, no whitespace.
24		hostName = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
25		// ipv6Zone is the zone of a link-local address ("eth0" in fe80::1%eth0).
26		ipv6Zone = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
27	)
28	
29	// flagKind is the type of a flag, which decides how it is registered and how
30	// its value is handed to nexusbench.FromEnv.
31	type flagKind int
32	
33	const (
34		kindString flagKind = iota
35		kindInt
36		kindDuration
37		kindBool
38		// kindConsent is a boolean whose true is the exact word "yes", the only
39		// value nexusbench accepts for NEXUS_BENCH_ACCEPT_EULA.
40		kindConsent
41	)
42	
43	// paramFlag is one flag that stands for one NEXUS_BENCH_* variable.
44	type paramFlag struct {
45		name  string
46		env   string
47		kind  flagKind
48		usage string
49	}
50	
51	// commonFlags are accepted by every subcommand.
52	func commonFlags() []paramFlag {
53		d := nexusbench.Defaults()
54		return []paramFlag{
55			{"context", "NEXUS_BENCH_CONTEXT", kindString, "kubectl context of the cluster (default " + d.Context + ")"},
56			{"namespace", "NEXUS_BENCH_NAMESPACE", kindString, "namespace of the bench, which down deletes (default " + d.Namespace + ")"},
57			{"http-nodeport", "NEXUS_BENCH_HTTP_NODEPORT", kindInt, fmt.Sprintf("NodePort of the REST API and the UI (default %d)", d.HTTPNodePort)},
58			{"docker-nodeport", "NEXUS_BENCH_DOCKER_NODEPORT", kindInt, fmt.Sprintf("NodePort of the Docker connector (default %d)", d.DockerNodePort)},
59			{"cpu-request", "NEXUS_BENCH_CPU_REQUEST", kindString, "CPU request (default " + d.CPURequest + ")"},
60			{"cpu-limit", "NEXUS_BENCH_CPU_LIMIT", kindString, "CPU limit (default " + d.CPULimit + ")"},
61			{"memory-request", "NEXUS_BENCH_MEMORY_REQUEST", kindString, "memory request (default " + d.MemoryRequest + ")"},
62			{"memory-limit", "NEXUS_BENCH_MEMORY_LIMIT", kindString, "memory limit (default " + d.MemoryLimit + ")"},
63			{"storage-size", "NEXUS_BENCH_STORAGE_SIZE", kindString, "size of the data volume (default " + d.StorageSize + ")"},
64			{"jvm-opts", "NEXUS_BENCH_JVM_OPTS", kindString, "JVM options of Nexus (default " + d.JVMOpts + ")"},
65			{"image", "NEXUS_BENCH_IMAGE", kindString, "Nexus image, without the tag (default " + d.Image + ")"},
66			{"image-tag", "NEXUS_BENCH_IMAGE_TAG", kindString, "Nexus image tag (default " + d.ImageTag + ")"},
67			{"upstream-image", "NEXUS_BENCH_UPSTREAM_IMAGE", kindString, "image of the bench upstream registry, without the tag (default " + d.UpstreamImage + ")"},
68			{"upstream-image-tag", "NEXUS_BENCH_UPSTREAM_IMAGE_TAG", kindString, "tag of the bench upstream registry image (default " + d.UpstreamImageTag + ")"},
69			{"upstream-url", "NEXUS_BENCH_UPSTREAM_URL", kindString, "upstream of the proxy repository (default http://bench-upstream.<namespace>.svc.cluster.local:5000)"},
70			{"anonymous", "NEXUS_BENCH_ANONYMOUS", kindBool, "enable anonymous access, --anonymous=false to disable (default true)"},
71			{"hosts", "NEXUS_BENCH_HOSTS", kindString, "comma-separated hosts the NodePorts are tried on (default 127.0.0.1 and the node address)"},
72			{"timeout", "NEXUS_BENCH_TIMEOUT", kindDuration, "how long up waits for Nexus (default " + d.Timeout.String() + ")"},
73			{"delete-timeout", "NEXUS_BENCH_DELETE_TIMEOUT", kindDuration, "how long down waits for the namespace to go (default " + d.DeleteTimeout.String() + ")"},
74			{"secrets", "NEXUS_BENCH_SECRETS", kindString, "secrets file, outside the repository (default under $XDG_STATE_HOME/devdesk/nexus-bench)"},
75			{"descriptor", "NEXUS_BENCH_DESCRIPTOR", kindString, "descriptor file (default internal/nexusbench/descriptor.json)"},
76		}
77	}
78	
79	// provisionFlags are accepted by the subcommands that provision Nexus.
80	func provisionFlags() []paramFlag {
81		return []paramFlag{
82			{"accept-eula", "NEXUS_BENCH_ACCEPT_EULA", kindConsent, "accept the Nexus Community Edition EULA on your behalf: read it first (default false; the variable counts only as the exact value yes)"},
83		}
84	}
85	
86	// restHostFlag names the flag that picks the host the admin credentials are sent to.
87	const restHostFlag = "rest-host"
88	
89	// flagSet is the flags of one subcommand.
90	type flagSet struct {
91		fs       *flag.FlagSet
92		specs    map[string]paramFlag
93		restHost *string
94	}
95	
96	// newFlagSet registers the flags of a subcommand. It prints nothing by itself:
97	// the caller reports a parse error on stderr and the help on stdout.
98	func newFlagSet(name string, provisions bool) *flagSet {
99		fs := flag.NewFlagSet("nexus-bench "+name, flag.ContinueOnError)
100		fs.SetOutput(io.Discard)
101		fs.Usage = func() {}
102		set := &flagSet{fs: fs, specs: map[string]paramFlag{}}
103		specs := commonFlags()
104		if provisions {
105			specs = append(specs, provisionFlags()...)
106		}
107		for _, spec := range specs {
108			set.specs[spec.name] = spec
109			switch spec.kind {
110			case kindString:
111				fs.String(spec.name, "", spec.usage)
112			case kindInt:
113				fs.Int(spec.name, 0, spec.usage)
114			case kindDuration:
115				fs.Duration(spec.name, time.Duration(0), spec.usage)
116			case kindBool, kindConsent:
117				fs.Bool(spec.name, false, spec.usage)
118			}
119		}
120		if provisions {
121			set.restHost = fs.String(restHostFlag, "", "host the REST API is reached on, and so the host the admin credentials are sent to (default "+loopbackHost+"); another host sends them in clear text")
122		}
123		return set
124	}
125	
126	// parse reads args. It returns flag.ErrHelp for -h and --help, and an error for
127	// an unknown flag, a value of the wrong type or an argument that is not a flag.
128	func (s *flagSet) parse(args []string) error {
129		if err := s.fs.Parse(args); err != nil {
130			return err
131		}
132		if s.fs.NArg() > 0 {
133			return fmt.Errorf("unexpected argument %q", s.fs.Arg(0))
134		}
135		return nil
136	}
137	
138	// printHelp writes the flags and their default to w.
139	func (s *flagSet) printHelp(w io.Writer) {
140		s.fs.SetOutput(w)
141		s.fs.PrintDefaults()
142		s.fs.SetOutput(io.Discard)
143	}
144	
145	// overlay returns getenv with every flag that was given laid over its
146	// NEXUS_BENCH_* variable: nexusbench.FromEnv then applies "flag, then variable,
147	// then default" in one place, with the same parsing and the same follow-the-
148	// namespace rule for the upstream URL.
149	func (s *flagSet) overlay(getenv func(string) string) func(string) string {
150		given := map[string]string{}
151		s.fs.Visit(func(f *flag.Flag) {
152			spec, ok := s.specs[f.Name]
153			if !ok {
154				return
155			}
156			value := f.Value.String()
157			if spec.kind == kindConsent {
158				value = map[bool]string{true: "yes", false: "no"}[value == "true"]
159			}
160			given[spec.env] = value
161		})
162		return func(name string) string {
163			if v, ok := given[name]; ok {
164				return v
165			}
166			return getenv(name)
167		}
168	}
169	
170	// restHostGiven returns the --rest-host value and whether it was set.
171	func (s *flagSet) restHostGiven() (string, bool) {
172		if s.restHost == nil {
173			return "", false
174		}
175		given := false
176		s.fs.Visit(func(f *flag.Flag) {
177			if f.Name == restHostFlag {
178				given = true
179			}
180		})
181		return *s.restHost, given
182	}
183	
184	// resolveParams returns the validated parameters of a run: defaults, then the
185	// NEXUS_BENCH_* variables, then the flags.
186	func (s *flagSet) resolveParams(getenv func(string) string) (nexusbench.Params, error) {
187		p, err := nexusbench.FromEnv(nexusbench.Defaults(), s.overlay(getenv))
188		if err != nil {
189			return p, err
190		}
191		return p, p.Validate()
192	}
193	
194	// validateRESTHost refuses what is not a host name or an IP address: a port, a
195	// path, a scheme, credentials or whitespace would change where the admin
196	// credentials go.
197	func validateRESTHost(host string) error {
198		if host == "" || len(host) > maxHostLen {
199			return fmt.Errorf("--%s: %q is not a host name or an IP address", restHostFlag, host)
200		}
201		if addr, ok := hostAddress(host); ok {
202			if zone := addr.Zone(); zone != "" && !ipv6Zone.MatchString(zone) {
203				return fmt.Errorf("--%s: %q has an unusable IPv6 zone", restHostFlag, host)
204			}
205			return nil
206		}
207		if !hostName.MatchString(host) {
208			return fmt.Errorf("--%s: %q is not a host name or an IP address (no port, scheme, path or credentials)", restHostFlag, host)
209		}
210		return nil
211	}
212	
213	// hostAddress parses host as an IP address, with or without the brackets of an
214	// IPv6 literal.
215	func hostAddress(host string) (netip.Addr, bool) {
216		if len(host) > 1 && strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
217			host = host[1 : len(host)-1]
218		}
219		addr, err := netip.ParseAddr(host)
220		return addr, err == nil
221	}
222	
223	// isLoopbackHost tells whether host stays on this machine.
224	func isLoopbackHost(host string) bool {
225		if strings.EqualFold(host, "localhost") {
226			return true
227		}
228		addr, ok := hostAddress(host)
229		return ok && addr.Unmap().IsLoopback()
230	}
