954		}
955	
956		// Order: the runner and the store exist before the cluster is touched;
957		// Deploy runs its own preflight(OpUp), so a preflight of the command is
958		// allowed but only before Deploy, and only for OpUp.
959		deploy, provision := h.index("deploy"), h.index("provision")
960		if deploy < 0 || provision < 0 || deploy > provision {
961			t.Fatalf("want deploy then provision, got %v", h.eventList())
962		}
963		for _, e := range []string{"newRunner", "newStore"} {
964			if i := h.index(e); i < 0 || i > deploy {
965				t.Errorf("%s must happen before Deploy, events: %v", e, h.eventList())
966			}
967		}
968		for _, op := range h.preflightOps {
969			if op != nexusbench.OpUp {
970				t.Errorf("up ran a preflight for %s, want OpUp only", opName(op))
971			}
972		}
973		if i := h.index("preflight:OpUp"); i > deploy {
974			t.Errorf("the preflight must come before Deploy, events: %v", h.eventList())
975		}
976		if h.has("destroy") {
977			t.Errorf("up destroyed something: %v", h.eventList())
978		}
979	
980		// What each step was given.
981		if h.deployRunner != nexusbench.Runner(h.runner) || h.deployProber != nexusbench.Prober(h.prober) || h.deployClock != nexusbench.Clock(h.clock) {
982			t.Error("Deploy was not given the runner, the prober and the clock of the deps")
983		}
984		if h.newInitialRunner != nexusbench.Runner(h.runner) || h.newInitialNamespace != "nexus-bench" {
985			t.Errorf("newInitial got (%v, %q), want the runner and the namespace", h.newInitialRunner, h.newInitialNamespace)
986		}
987		if h.provisionInitial != nexusbench.InitialPassword(h.initial) || h.provisionStore != nexusbench.SecretStore(h.store) {
988			t.Error("Provision was not given the InitialPassword of newInitial and the store of newStore")
989		}
990		if want := nexusbench.RESTBaseURL("127.0.0.1", h.provisionParams); h.provisionURL != want || want != "http://127.0.0.1:30481" {
991			t.Errorf("Provision base URL = %q, want %q", h.provisionURL, want)
992		}
993		if !h.provisionParams.AcceptEULA {
994			t.Error("--accept-eula did not reach Provision")
995		}
996		if h.descriptorSeenAtProvision {
997			t.Error("the descriptor existed before Provision ran")
998		}
999	
1000		// The descriptor: what the library writes for these inputs, nothing else.
1001		p := nexusbench.Defaults()
1002		got, err := os.ReadFile(h.descriptor)
1003		if err != nil {
1004			t.Fatalf("no descriptor written: %v", err)
1005		}
1006		if want := wantDescriptorBytes(t, p, h.deployRes, h.provisionRes); !bytes.Equal(got, want) {
1007			t.Errorf("descriptor bytes differ from BuildDescriptor:\n got %s\nwant %s", got, want)
