1086			}},
1087			{"up: deploy fails", "up", func(h *harness) { h.deployErr = be }},
1088			{"provision: preflight fails", "provision", func(h *harness) { h.preflightErr = be }},
1089		}
1090		for _, st := range steps {
1091			for _, existing := range []bool{false, true} {
1092				name := st.name + " / no descriptor yet"
1093				if existing {
1094					name = st.name + " / a descriptor exists"
1095				}
1096				t.Run(name, func(t *testing.T) {
1097					h := newHarness(t)
1098					st.setup(h)
1099					var before []byte
1100					if existing {
1101						other := nexusbench.Defaults()
1102						other.ImageTag = "3.97.0"
1103						before = h.writeDescriptor(other, nexusbench.DeployResult{}, nexusbench.ProvisionResult{NexusVersion: "3.97.0-01"})
