129	// scaleUpstream is the one write of EnsureUpstream. A failed write is not
130	// retried: the scale is not what a second try would fix.
131	func (d *deployer) scaleUpstream(ctx context.Context, replicas int) error {
132		args := []string{"scale", "deployment/" + upstreamDeployment, fmt.Sprintf("--replicas=%d", replicas), "-n", d.pf.p.Namespace, applyTimeout}
133		_, errOut, err := d.pf.r.Run(ctx, nil, args...)
134		if err == nil {
135			return nil
136		}
137		if cerr := ctx.Err(); cerr != nil {
138			return cerr
139		}
140		return d.pf.failure("scale the Deployment "+upstreamDeployment, args, string(errOut), err)
141	}
