			URLs: hostURLs(hosts, p.HTTPNodePort),
		},
		DockerConnectors: []DockerConnector{{
			Repository: dockerGroupRepository, NodePort: p.DockerNodePort, ContainerPort: dockerContainerPort,
			URLs: hostURLs(hosts, p.DockerNodePort),
