368	func TestIntegrationLifecycle(t *testing.T) {
369		requireBench(t)
370		if os.Getenv(benchLifecycleEnv) != "1" {
371			t.Skipf("set %s=1 as well to run the destructive lifecycle (it deletes the bench namespace)", benchLifecycleEnv)
372		}
373	
374		p, err := FromEnv(Defaults(), os.Getenv)
375		if err != nil {
376			t.Fatalf("parameters: %v", err)
377		}
378		if !p.AcceptEULA {
379			t.Fatalf("the lifecycle provisions Nexus, which needs the EULA accepted: read it, then set %s=yes", envAcceptEULA)
380		}
381		if deadline, ok := t.Deadline(); ok && time.Until(deadline) < lifecycleMinTimeout {
382			t.Fatalf("go test stops this run in %s; the lifecycle needs at least %s: rerun with -timeout 60m", time.Until(deadline).Round(time.Second), lifecycleMinTimeout)
383		}
384		if err := p.Validate(); err != nil {
385			t.Fatalf("parameters: %v", err)
386		}
387	
388		secretsPath := p.SecretsPath
389		if secretsPath == "" {
390			secretsPath = secretsPathFor(t, p.Context, p.Namespace)
391		}
392		runner, err := NewExecRunner(p.Context)
393		if err != nil {
394			t.Fatalf("NewExecRunner: %v", err)
395		}
396		store, err := NewFileStore(secretsPath)
397		if err != nil {
398			t.Fatalf("NewFileStore: %v", err)
399		}
400		clock, prober, out := NewClock(), NewProber(), logWriter{t}
401		ctx := context.Background()
402		initial := NewKubectlInitialPassword(runner, p.Namespace)
403	
404		up := func() {
405			t.Helper()
406			if _, err := Deploy(ctx, runner, prober, clock, p, out); err != nil {
407				t.Fatalf("up: %v", err)
408			}
409		}
410		provision := func() ProvisionResult {
411			t.Helper()
412			if _, err := RunPreflight(ctx, runner, p, OpProvision); err != nil {
413				t.Fatalf("provision preflight: %v", err)
414			}
415			res, err := Provision(ctx, RESTBaseURL(loopbackHost, p), initial, store, p, out)
416			if err != nil {
417				t.Fatalf("provision: %v", err)
418			}
419			return res
420		}
421		down := func() {
422			t.Helper()
423			if err := Destroy(ctx, runner, clock, store, p, out); err != nil {
424				t.Fatalf("down: %v", err)
425			}
426			_, stderr, err := runner.Run(ctx, nil, "get", "namespace", p.Namespace)
427			if err == nil || !isNotFound(string(stderr)) {
428				t.Fatalf("after down, `get namespace %s` = (err %v), want NotFound", p.Namespace, err)
429			}
430		}
431		snapshot := func() benchSnapshot {
432			t.Helper()
433			secrets, found, err := store.Load()
434			if err != nil || !found {
435				t.Fatalf("read the secrets (found %v): %v", found, err)
436			}
437			c := newClient(RESTBaseURL(loopbackHost, p), adminUserID, secrets.AdminPassword)
438			defer c.closeIdle()
439			return snapshotBench(ctx, t, c)
440		}
441	
442		t.Log("first up and provision")
443		up()
444		desc := BuildDescriptor(p, DeployResult{}, provision(), SeedResult{})
445		first := snapshot()
446		for _, want := range desc.Repositories {
447			if !slices.Contains(first.Repositories, want.Name) {
448				t.Fatalf("after provision the instance lists %v, want the repository %s of the descriptor", first.Repositories, want.Name)
449			}
450		}
451	
452		t.Log("second up and provision: nothing changes")
453		up()
454		provision()
455		if second := snapshot(); !reflect.DeepEqual(first, second) {
456			t.Errorf("a second up and provision changed the instance:\nfirst  %+v\nsecond %+v", first, second)
457		}
458	
459		t.Log("down")
460		down()
461	
462		t.Log("up on a fresh instance")
463		up()
464		password, ok, err := initial.Read(ctx)
465		if err != nil {
466			t.Fatalf("read the initial password: %v", err)
467		}
468		if !ok || password == "" {
469			t.Error("a fresh instance has no admin.password in the pod")
470		}
471	
472		t.Log("final down")
473		down()
474	}
