			code, stdout, stderr := h.run(append([]string{"seed"}, tt.args...)...)
			if code != 0 {
				t.Fatalf("exit code = %d\nstdout: %s\nstderr: %s", code, stdout, stderr)
			}
			if h.seedURL != tt.wantURL {
