func TestSeedOfANonDefaultBenchWarnsNotToCommitTheDescriptor(t *testing.T) {
	for _, tt := range []struct {
		name string
		args []string
		want bool
	}{
		{"default bench, tuned timeout", []string{"--timeout", "5m"}, false},
